pub const FRAMEWORK_RESERVED_CONTRIBUTIONS: [semio_framework_manifest_app_surface::ReservedContribution; 2] = [semio_framework_time_travel_actions::RESERVED, semio_framework_tool_run_actions::RESERVED];
